def score(program: str) -> float:
    import io, tokenize
    try:
        toks = [x.string for x in tokenize.generate_tokens(io.StringIO(program).readline) if x.string.strip()]
    except Exception:
        return 0.0
    u = len(set(toks))
    a = u / (u + 50.0)
    b = u / len(toks)
    return min(1.0, 0.5 * a + 0.5 * b)

def ratio(a, b) -> float:
    return a / (a + b)


def size(src: str) -> float:
    return ratio(len(src), 2000.0)


def shape(src: str) -> float:
    return ratio(src.count("\n") + 1, 60.0)


def score(program: str) -> float:
    """Pure."""
    return (size(program) + shape(program)) / 2

def score(program: str) -> float:
    import ast
    try:
        tree = ast.parse(program)
        node_count = sum(1 for _ in ast.walk(tree))
        return min(node_count / 100.0, 1.0)
    except Exception:
        return 0.0

